  ArticleContent result=new ArticleContent();result.title=title;walk(chosen,result,new HashSet<>());if(!structured.isEmpty()&&structured.length()>Math.max(240,result.characters*1.3)){ArticleContent data=extract(structured,base,true);if(data.characters>result.characters){result=data;result.title=title;}}if(!lead.isEmpty()&&result.blocks.stream().noneMatch(b->b.kind.equals("img")&&imageKey(b.value).equals(imageKey(lead))))result.blocks.add(0,new Block("img",lead));if(result.blocks.isEmpty()&&!chosen.text().isEmpty())result.add("p",chosen.text());result.preview=preview;result.published=publication;return result;
