 static String structuredBody(Document document){String best="";for(Element script:document.select("script[type=application/ld+json]"))try{String body=structuredValue(new org.json.JSONTokener(script.data()).nextValue());if(body.length()>best.length())best=body;}catch(Exception ignored){}return best;}
 static String publication(Document document){for(Element e:document.select("meta[property=article:published_time],meta[name=citation_publication_date],meta[name=DC.date],meta[name=dc.date],meta[itemprop=datePublished],time[itemprop=datePublished]")){String value=e.hasAttr("content")?e.attr("content"):e.attr("datetime");if(!value.isEmpty())return value.replace('/','-');}for(Element e:document.select("script[type=application/ld+json]"))try{String value=publicationValue(new org.json.JSONTokener(e.data()).nextValue());if(!value.isEmpty())return value;}catch(Exception ignored){}return "";}
 static String publicationValue(Object value){if(value instanceof org.json.JSONObject){org.json.JSONObject object=(org.json.JSONObject)value;if(object.optString("@type").matches("(?i).*(?:Article|BlogPosting).*")){String date=object.optString("datePublished");if(!date.isEmpty())return date;}return publicationValue(object.opt("@graph"));}if(value instanceof org.json.JSONArray){org.json.JSONArray array=(org.json.JSONArray)value;for(int n=0;n<array.length();n++){String date=publicationValue(array.opt(n));if(!date.isEmpty())return date;}}return "";}
 static String structuredValue(Object value)throws org.json.JSONException{String best="";if(value instanceof org.json.JSONObject){org.json.JSONObject object=(org.json.JSONObject)value;String type=object.optString("@type");if(type.matches("(?i).*(?:NewsArticle|Article|ReportageNewsArticle|BlogPosting|ScholarlyArticle).*")){String body=object.optString("articleBody","");if(!body.isEmpty()){if(body.contains("<p")||body.contains("<div"))best=body;else{StringBuilder escaped=new StringBuilder();for(String paragraph:body.split("\n+"))escaped.append("<p>").append(org.jsoup.nodes.Entities.escape(paragraph)).append("</p>");best=escaped.toString();}}}Object graph=object.opt("@graph");String nested=structuredValue(graph);if(nested.length()>best.length())best=nested;}else if(value instanceof org.json.JSONArray){org.json.JSONArray array=(org.json.JSONArray)value;for(int n=0;n<array.length();n++){String body=structuredValue(array.opt(n));if(body.length()>best.length())best=body;}}return best;}
 static org.jsoup.select.Elements candidates(Document document){org.jsoup.select.Elements found=document.select("[itemprop=articleBody],.article-body,.article__body,.article-content,.story-body,.story__content,.story-content,.content__article-body,.articlebodycontent,.story_details,.storyDetail,.storyBody,.ssrcss-11r1m41-RichTextComponentWrapper,.sdc-article-body,[data-component-name=ui-article-body],[data-testid=article-body]");if(found.isEmpty())found=document.select("article");if(found.isEmpty())found=document.select("main,[role=main]");return found;}
 static boolean captionText(String text){return text.length()<700&&(text.matches("(?iu)^(?:photo(?:graph)?|image|picture|illustration|फोटो|तस्वीर|चित्र)(?:\\s+(?:credit|courtesy|source))?\\s*[:|©].+")||text.matches("(?iu).{0,550}\\((?:photo|image|picture|फोटो|तस्वीर)(?:\\s+(?:credit|courtesy|source))?\\s*[:|©].+\\)\\s*$")||text.matches("(?iu).{0,550}\\b(?:hide caption|toggle caption|show caption)\\s*$"));}
 static boolean accessNotice(String text){return text.matches("(?is)^You have a preview view of this article while we are checking your access\\.(?: When we have confirmed access, the full article content will load\\.)?$");}
 static boolean noiseText(String value){String text=value.replace('\u00a0',' ').replaceAll("\\s+"," ").trim();if(accessNotice(text)||captionText(text))return true;if(text.isEmpty()||text.matches("[\\p{P}\\p{S}\\s]+"))return true;if(text.matches("(?iu)^(?:image(?: \\d+)?|enlarge image|view image|view larger image|click to enlarge|tap to enlarge|hide caption|show caption|toggle caption|read in app|open in app|download (?:the )?app|text size|font size|back to top|expand|fullscreen|zoom in|zoom out|save(?: article| story| for later)?|saved|unsave|bookmark(?: this article)?|remove bookmark|listen|सहेजें|सेव|कॉपी लिंक|शेयर|विज्ञापन|खबरें और भी हैं|पूरी खबर पढ़ें|ऐप खोलें|Published|Updated|Subsection|Published\\s*[-:].*|Updated\\s*[-:].*|\\d+\\s*(?:min(?:ute)?s? read|घंटे पहले|दिन पहले)|Sign in|Log in|Subscribe now|Accept all cookies|All rights reserved)[.!]?$"))return true;if(text.length()>240)return false;if(narrationNoise(text))return true;return text.matches("(?i)^(?:advertisement|advertising|ad(?:vert)?(?:isement)?(?:vertising)?(?:\\s*[-:|]\\s*.*)?|sponsored(?: content| links| stories)?|promoted content|(?:story|article|content|reading)\\s+(?:continues?|continued)(?:\\s+below)?(?:\\s+(?:this|the|an?))?\\s+(?:ad|advertisement)[.!]?|(?:continue reading|scroll down)(?:\\s+below)?(?:\\s+(?:this|the|an?))?\\s+(?:ad|advertisement)[.!]?|(?:story|article) continues? below[.!]?|(?:hide|skip|remove) (?:ad|advertisement)s?|share(?: this)?(?: article| story| post)?(?: on .*)?|follow us(?: on .*)?|follow (?:us )?on (?:facebook|twitter|instagram|whatsapp|telegram|x)|(?:facebook|twitter|whatsapp|telegram|linkedin|instagram|pinterest|copy link|print|email|share|post comment|add comment))$")||text.matches("(?i)^.*\\b(?:story|article) continues? below (?:this |the |an? )?(?:ad|advertisement)[.!]?$ ".trim());}
 static boolean narrationNoise(String text){if(text.matches("(?i)^(?:your feedback (?:has|have) been (?:successfully )?(?:saved|recorded|submitted|reported)(?: successfully| succesfully)?|feedback (?:saved|submitted|recorded)|(?:ai[- ]translation|translate (?:this (?:article|story)|to .+)|show original|view original|original language|translation feedback|report feedback|was this translation (?:helpful|accurate)))[.!?]?$")||text.matches("(?i)^this (?:article|story|translation) (?:is|was|has been) (?:translated|generated) (?:by|using|with) (?:ai|artificial intelligence).{0,140}$"))return true;return text.matches("(?i)^(?:(?:0\\.[257]5?|[123](?:\\.[0257]5?)?)\\s*[x×]\\s*)+$")||text.matches("(?i)^(?:ai narration|ai[- ](?:generated|powered) (?:audio|narration)|audio narration|listen to (?:this |the )?(?:article|story)|listen to article|play(?:back)? speed|narration speed|audio speed|rate this (?:audio|narration)|was this (?:helpful|useful)|thank(?:s| you)(?: so much)? for (?:your )?feedback)[.!?]?$ ".trim())||text.matches("(?i)^(?:this (?:audio|narration)(?: is| was| has been)?|the (?:audio|narration)(?: is| was| has been)?) (?:ai[- ]generated|generated (?:by|using|with) (?:ai|artificial intelligence)).{0,180}$")||text.matches("(?i)^thank you[,.! ]+(?:we (?:have |have received |received )?(?:your )?feedback|your feedback.{0,100})[.!]?$ ".trim());}
 static boolean boundary(String text){if(text.trim().matches("(?is)^(?:A version of this article appears in print|This article appears in print|Read more about the author|More about the author|About the author|About the reporter)(?:[ :.,].*)?$"))return true;return text.trim().matches("(?i)^(?:also read|read also|read next|read more|related(?: articles| stories| news| coverage| topics)?|more (?:on this (?:story|topic)|about this (?:story|topic)|premium stories|articles|stories|news|from .+)|recommended(?: for you| articles| stories)?|you (?:may|might) (?:also )?like|latest (?:news|stories|articles)|trending(?: now| stories)?|most (?:read|popular)|around the web|from around the web|sponsored (?:stories|links)|top (?:stories|news))(?:\\s*[:|–-].*)?$");}
