 static void clean(Document document){
  // Publishers often use generic div/span elements for captions and photo credits.
  // Remove those before a parent paragraph's text() flattens them into story prose.
  java.util.regex.Pattern captions=java.util.regex.Pattern.compile("(?i)(?:^|[ _-])(?:figcaption|caption(?:s|text)?|(?:image|img|photo|picture|media|figure)[ _-]?(?:caption|credit|copyright|description)|credit(?:s|text)?)(?:$|[ _-])");
  for(Element e:new ArrayList<>(document.getAllElements())){if(e.parent()==null||e.normalName().equals("img"))continue;String markers=(e.id()+" "+e.className()+" "+e.attr("itemprop")+" "+e.attr("data-component")+" "+e.attr("data-component-name")+" "+e.attr("data-testid")).replaceAll("([a-z])([A-Z])","$1 $2");if(e.normalName().equals("figcaption")||captions.matcher(markers).find()){
   // Keep article artwork when a publisher wraps the image and caption together.
   for(Element image:new ArrayList<>(e.select("img")))e.before(image);
   e.remove();
  }}
  java.util.regex.Pattern widgets=java.util.regex.Pattern.compile("(?i)(?:^|[ _-])(?:ai[-_ ]?(?:info|narrative)[-_ ]?(?:popup|backdrop|actions|controls)?|translation[-_ ]?(?:toggle|controls|widget|popup|disclaimer|selector|notice)|language[-_ ]?(?:selector|switcher)|lang[-_ ]?select|narration[-_ ]?text|feedback[-_ ]?(?:toast|popup|rating)|audio[-_ ]?player|article[-_ ]?audio|text[-_ ]?to[-_ ]?speech|tts[-_ ]?(?:player|controls|widget)|ai[-_ ]?narration|narration[-_ ]?(?:player|controls|widget)|listen[-_ ]?(?:article|widget|player)|feedback[-_ ]?(?:widget|form|controls|message)|audio[-_ ]?feedback|advert(?:isement|ising)?|ads?|adslot|adcontainer|adwrapper|adbanner|adunit|adsbygoogle|sponsored|outbrain|taboola|related|also[-_ ]?read|read[-_ ]?(?:more|next)|other[-_ ]?(?:articles|stories)|recommend(?:ed|ations)?|recirculation|trending|most[-_ ]?(?:read|popular)|social[-_ ]?(?:links?|icons?|buttons?|share|media)|share[-_ ]?(?:links?|icons?|buttons?|tools?|bar|widget)|sharing|addthis|addtoany|byline|author[-_ ]?(?:name|info|details|bio|biography|profile)|reporter[-_ ]?(?:bio|biography|profile)|print[-_ ]?(?:edition|information)|article[-_ ]?(?:footer|endnotes)|(?:update[-_ ]?)?publish[-_ ]time|article[-_ ]published[-_ ]time[-_ ]end|article[-_ ]date|date[-_ ]time|timestamp|dateline|breadcrumb|read[-_ ]time|newsletter|cookie|consent|privacy[-_ ]?(?:options|controls|settings)|(?:embed|external[-_ ]content)[-_ ]?(?:placeholder|fallback|roadblock)|promo(?:tion)?|follow[-_ ]?us|(?:story|article)[-_ ]?(?:list|cards|recommendations)|more[-_ ]?(?:stories|articles|news)|latest[-_ ]?(?:stories|articles|news))(?:$|[ _-])");
  for(Element e:new ArrayList<>(document.getAllElements())){if(e.parent()==null)continue;String markers=(e.id()+" "+e.className()+" "+e.attr("data-component")+" "+e.attr("data-component-name")+" "+e.attr("data-testid")+" "+e.attr("aria-label")).replaceAll("([a-z])([A-Z])","$1 $2");if(widgets.matcher(markers).find()){e.remove();continue;}String tag=e.normalName();if((tag.equals("a")||e.attr("role").equals("button"))&&noiseText(e.text())){e.remove();continue;}if(tag.equals("a")){String href=e.attr("href").toLowerCase(Locale.ROOT);if(href.matches(".*(?:facebook\\.com/(?:sharer|share)|twitter\\.com/(?:intent|share)|x\\.com/intent|api\\.whatsapp\\.com|wa\\.me/|linkedin\\.com/(?:share|sharing)|t\\.me/share|pinterest\\.com/pin/create).*"))e.remove();}else if(e.childrenSize()==0&&!e.text().isEmpty()&&noiseText(e.text()))e.remove();}
 }
 static boolean followingStory(Element heading){for(Element next=heading.nextElementSibling();next!=null;next=next.nextElementSibling()){if(boundary(next.text()))continue;if(linkList(next))continue;if(next.normalName().equals("p")&&next.text().length()>160&&!noiseText(next.text()))return true;for(Element paragraph:next.select("p"))if(paragraph.text().length()>160&&!linkList(paragraph)&&!noiseText(paragraph.text()))return true;}return false;}
 static double score(Element e){int paragraphs=0;for(Element p:e.select("p"))paragraphs+=p.text().length();int links=0;for(Element a:e.select("a"))links+=a.text().length();return paragraphs+Math.min(200,e.select("img").size()*30)-links*.8;}
 void add(String kind,String value){if(kind.equals("caption"))return;value=value.replace("\u00ad","").replace("\u200b","").trim();if(value.isEmpty()||(!kind.equals("img")&&(noiseText(value)||boundary(value)))||blocks.size()>=500||characters>150000)return;if(!kind.equals("img")&&value.length()>80)for(Block previous:blocks)if(previous.kind.equals(kind)&&previous.value.equals(value))return;blocks.add(new Block(kind,value));if(!kind.equals("img"))characters+=value.length();}
 static void walk(Element root,ArticleContent out,Set<String> images){for(Node node:root.childNodes()){if(out.ended||out.blocks.size()>=500)return;if(node instanceof TextNode){String text=((TextNode)node).text().trim();if(boundary(text)&&!text.matches("(?i)^(?:also read|read also|read more|read next)[: ]*$")){out.ended=true;return;}if(!text.isEmpty())out.add("p",text);continue;}if(!(node instanceof Element))continue;Element e=(Element)node;String tag=e.normalName();if(boundary(e.text())&&tag.matches("h[1-6]|strong|div|section|p|span")){boolean inline=e.text().trim().matches("(?i)^(?:also read|read also|read more|read next)[: ]*$");if(!inline||!followingStory(e)){out.ended=true;return;}continue;}if(linkList(e)&&e.text().length()<1200)continue;if(tag.equals("img")){String image=image(e);if(!image.isEmpty()&&images.size()<24&&images.add(imageKey(image)))out.add("img",image);}else if(tag.matches("h[1-6]")){if(!tag.equals("h1"))out.add("heading",e.text());}else if(tag.equals("p")||tag.equals("blockquote")||tag.equals("figcaption")||tag.equals("li")||tag.equals("pre")){if(!e.text().isEmpty())out.add(tag.equals("li")?"li":tag.equals("figcaption")?"caption":"p",e.text());for(Element image:e.select("img")){String value=image(image);if(!value.isEmpty()&&images.size()<24&&images.add(imageKey(value)))out.add("img",value);}}else if(tag.equals("table")){for(Element row:e.select("tr"))out.add("p",row.text());}else walk(e,out,images);}}
 static String image(Element e){try{int width=Integer.parseInt(e.attr("width"));int height=Integer.parseInt(e.attr("height"));if(width<40&&height<40)return "";}catch(Exception ignored){}String source=e.attr("data-src");if(source.isEmpty())source=e.attr("data-original");String srcset=e.attr("srcset");if(srcset.isEmpty())srcset=e.attr("data-srcset");if(source.isEmpty()&&!srcset.isEmpty()){int best=0;for(String choice:srcset.split(",")){String[] pair=choice.trim().split("\\s+");int size=pair.length>1?number(pair[1]):1;if(size>best&&size<=1600){best=size;source=pair[0];}}}if(source.isEmpty())source=e.attr("src");return url(e.baseUri(),source);}
 static String imageKey(String value){try{URI uri=new URI(value);String host=uri.getHost()==null?"":uri.getHost().toLowerCase(Locale.ROOT);String path=uri.getPath()==null?"":uri.getPath();path=path.replaceAll("(?i)-\\d{2,5}x\\d{2,5}(?=\\.[a-z]{3,4}$)","").replaceAll("(?i)-(?:superJumbo|articleLarge|articleInline|thumbLarge|thumbWide|mediumThreeByTwo\\d+)(?=\\.[a-z]{3,4}$)","");if(host.endsWith("bbci.co.uk"))path=path.replaceAll("/(?:news|standard)/\\d+/","/news/SIZE/");TreeMap<String,String> query=new TreeMap<>();if(uri.getRawQuery()!=null)for(String part:uri.getRawQuery().split("&")){String[] pair=part.split("=",2);String key=java.net.URLDecoder.decode(pair[0],"UTF-8").toLowerCase(Locale.ROOT);if(key.matches("w|h|width|height|resize|fit|crop|quality|q|auto|format|fm|dpr|s|output|imwidth|imheight|utm_.*"))continue;query.put(pair[0],pair.length>1?pair[1]:"");}return host+path+(query.isEmpty()?"":"?"+query.toString());}catch(Exception e){return value;}}
 static int number(String value){try{return Integer.parseInt(value.replaceAll("[^0-9]",""));}catch(Exception e){return 1;}}
